python3 << 'ENDSCRIPT'
from scapy.all import *
pkts = rdpcap('/work/workstation.pcap')

# Extract hex patterns from DNS queries  
print("Extracting hex patterns:")
for pkt in pkts:
    try:
        dns = pkt['DNS']
        if dns.qr == 0:  # Query
            raw_name = str(dns.qd.qname)
            if 'cdn' in raw_name.lower():
                parts = raw_name.split('.')
                if len(parts) >= 4 and parts[-1] == 'test.':
                    hex_part = parts[0]
                    clean = ''.join(c for c in hex_part if c in '0123456789abcdefABCDEF')
                    if len(clean) % 2 == 0 and len(clean) >= 2:
                        try:
                            decoded = bytes.fromhex(clean).decode('utf-8', errors='ignore')
                            print(f"{decoded}")
                        except Exception as e:
                            pass
    except:
        pass
ENDSCRIPT
